files.content:
:root {
  --bg: #1b1f3b;
  --card: #262b52;
  --accent: #f4c542;
  --bar: #7c8cff;
  --bar-compare: #f4c542;
  --bar-sorted: #4ade80;
  --text: #f5f6ff;
  --muted: #b9bce0;
  --shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 50% 0%, #2a3060 0%, var(--bg) 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border-radius: 18px;
  padding: 28px 24px;
  box-shadow: var(--shadow);
  border: 2px solid #3a4074;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 0.02em;
}

.subtitle {
  margin: 0 0 22px;
  color: var(--muted);
  font-size: 0.95rem;
}

.bars {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 6px;
  height: 220px;
  padding: 12px;
  background: #1f2344;
  border-radius: 12px;
  border: 2px solid #3a4074;
  overflow: hidden;
}

.bar {
  flex: 1 1 0;
  min-width: 0;
  background: var(--bar);
  border-radius: 4px 4px 0 0;
  border: 2px solid transparent;
  transition: height 0.18s ease, background-color 0.18s ease, border-color 0.18s ease;
  position: relative;
}

.bar.compare {
  background: var(--bar-compare);
  border-color: #fff;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.35);
}

.bar.sorted {
  background: var(--bar-sorted);
}

.controls {
  display: flex;
  gap: 12px;
  margin: 22px 0 16px;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 140px;
  padding: 12px 18px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border-radius: 10px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.08s ease, background-color 0.15s ease, box-shadow 0.15s ease;
}

.btn-primary {
  background: var(--accent);
  color: #1b1f3b;
}

.btn-primary:hover:not(:disabled) {
  background: #ffd95e;
}

.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--muted);
}

.btn-secondary:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.08);
}

.btn:active:not(:disabled) {
  transform: translateY(1px) scale(0.99);
}

.btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.status {
  margin: 0;
  padding: 12px 14px;
  background: #1f2344;
  border-radius: 10px;
  border-left: 4px solid var(--accent);
  color: var(--muted);
  font-size: 0.95rem;
  min-height: 1.5em;
}

.status.done {
  color: #d1fadf;
  border-left-color: var(--bar-sorted);
}

@media (max-width: 400px) {
  .card { padding: 22px 16px; }
  .bars { height: 180px; gap: 4px; padding: 8px; }
  h1 { font-size: 1.35rem; }
}

const BAR_COUNT = 10;
const MIN_HEIGHT = 20;
const MAX_HEIGHT = 100;

const barsEl = document.getElementById('bars');
const shuffleBtn = document.getElementById('shuffle');
const stepBtn = document.getElementById('step');
const statusEl = document.getElementById('status');

let values = [];
let barEls = [];
let i = 0;
let j = 0;
let swapped = false;
let sorted = false;

function randomValues() {
  return Array.from({ length: BAR_COUNT }, () =>
    Math.floor(Math.random() * (MAX_HEIGHT - MIN_HEIGHT + 1)) + MIN_HEIGHT
  );
}

function render() {
  barsEl.innerHTML = '';
  barEls = values.map((v, idx) => {
    const bar = document.createElement('div');
    bar.className = 'bar';
    bar.style.height = v + '%';
    bar.dataset.index = idx;
    bar.title = 'Bar ' + (idx + 1) + ': ' + v;
    barsEl.appendChild(bar);
    return bar;
  });
}

function clearHighlights() {
  barEls.forEach((b) => b.classList.remove('compare'));
}

function markSorted() {
  sorted = true;
  clearHighlights();
  barEls.forEach((b) => b.classList.add('sorted'));
  stepBtn.disabled = true;
  statusEl.textContent = 'Sorted! All bars are in order.';
  statusEl.classList.add('done');
}

function resetState() {
  i = 0;
  j = 0;
  swapped = false;
  sorted = false;
  stepBtn.disabled = false;
  clearHighlights();
  barEls.forEach((b) => b.classList.remove('sorted'));
  statusEl.classList.remove('done');
}

function shuffle() {
  values = randomValues();
  render();
  resetState();
  statusEl.textContent = 'Shuffled. Press Step to compare two bars.';
}

function step() {
  if (sorted) return;

  clearHighlights();

  // One comparison: compare values[j] and values[j + 1]
  const a = j;
  const b = j + 1;
  barEls[a].classList.add('compare');
  barEls[b].classList.add('compare');

  if (values[a] > values[b]) {
    const tmp = values[a];
    values[a] = values[b];
    values[b] = tmp;
    barEls[a].style.height = values[a] + '%';
    barEls[b].style.height = values[b] + '%';
    barEls[a].title = 'Bar ' + (a + 1) + ': ' + values[a];
    barEls[b].title = 'Bar ' + (b + 1) + ': ' + values[b];
    swapped = true;
    statusEl.textContent = 'Compared bars ' + (a + 1) + ' and ' + (b + 1) + ': swapped.';
  } else {
    statusEl.textContent = 'Compared bars ' + (a + 1) + ' and ' + (b + 1) + ': no swap.';
  }

  // Advance the bubble sort state machine by exactly one comparison
  j++;
  if (j >= BAR_COUNT - 1 - i) {
    if (!swapped) {
      markSorted();
      return;
    }
    i++;
    j = 0;
    swapped = false;
    if (i >= BAR_COUNT - 1) {
      markSorted();
      return;
    }
  }
}

shuffleBtn.addEventListener('click', shuffle);
stepBtn.addEventListener('click', step);

// Initial random bars
shuffle();
